const {chromium}=require('playwright');const fs=require('fs');const assert=require('node:assert/strict');
(async()=>{const base=process.env.QA_BASE||'http://127.0.0.1:3123';const out='.qa/seo-content-20260923/'+(base.includes('127.0.0.1')?'local':'live');fs.mkdirSync(out,{recursive:true});const b=await chromium.launch({headless:true});const results=[];
for(const width of [1440,390]){const c=await b.newContext({viewport:{width,height:900},reducedMotion:'reduce'});const p=await c.newPage();const errors=[],failed=[];p.on('pageerror',e=>errors.push(e.message));p.on('requestfailed',r=>failed.push({url:r.url(),error:r.failure()?.errorText}));
for(const slug of ['mathe-uebungen-kinder','mathe-uebungen-5-klasse','deutsch-uebungen-3-klasse','deutsch-uebungen-kinder']){const r=await p.goto(base+'/'+slug,{waitUntil:'networkidle'});assert.equal(r.status(),200);await p.locator('h1').waitFor();assert.equal(await p.locator('h1').count(),1);assert.equal(await p.locator('link[rel=canonical]').getAttribute('href'),'https://www.cleverli.ch/'+slug);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
if(slug==='mathe-uebungen-kinder'){assert.equal(await p.title(),'Mathe Übungen für Kinder der 1. bis 6. Klasse | Cleverli');assert.equal(await p.locator('h1').innerText(),'Mathe üben für die Schweizer Primarschule');assert.ok((await p.locator('meta[property="og:title"]').getAttribute('content')).includes('1. bis 6. Klasse'));}
if(slug.includes('-klasse')){const d=p.locator('section[aria-labelledby="worked-examples-heading"] details');assert.equal(await d.count(),3);for(let i=0;i<3;i++){await d.nth(i).locator('summary').click();assert.ok(await d.nth(i).evaluate(e=>e.open));assert.ok((await d.nth(i).innerText()).includes('Lösung:'));await d.nth(i).locator('summary').focus();await p.keyboard.press('Enter');assert.ok(await d.nth(i).evaluate(e=>!e.open));}await d.first().locator('summary').click();const faqs=await p.locator('script[type="application/ld+json"]').allTextContents();const faq=faqs.map(x=>JSON.parse(x)).find(x=>x['@type']==='FAQPage');for(const q of faq.mainEntity)assert.ok((await p.locator('main').innerText()).includes(q.name));const a=p.locator('section[aria-labelledby="worked-examples-heading"] a').first();const href=await a.getAttribute('href');await a.click();await p.waitForURL('**'+href);await p.goto(base+'/'+slug,{waitUntil:'networkidle'});await p.locator('section[aria-labelledby="worked-examples-heading"] summary').first().click();}
await p.screenshot({path:`${out}/${slug}-${width}.png`,fullPage:true});results.push({slug,width,status:200});}
assert.deepEqual(errors,[]);results.push({width,pageErrors:errors,failedRequests:failed});await c.close();}await b.close();fs.writeFileSync(out+'/results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));})().catch(e=>{console.error(e);process.exit(1)});
